-- =============================================================================
-- Maestro de motivos de reclamo de Mercado Libre (ADR-145, sobre ADR-132).
--
-- Tabla de referencia de PLATAFORMA (sin tenant_id): el mismo código significa
-- lo mismo para todos los negocios. La clave es el código de ML (PDD9939), no
-- un uuid, igual que `features.key` o `payment_providers.key`: es el id que
-- trae `ml_claims.reason_id` y lo que guarda `ml_gestor_settings.exclusion_reasons`.
--
-- Lectura: authenticated. Escritura: sólo service_role (el seed de acá y la
-- Edge ml_api, acción `reasons_fill`, que completa desde
-- GET /post-purchase/v1/claims/reasons/{id} los códigos que falten).
--
-- Seed: 622 motivos del sitio MLA leídos con GET reales a la API el
-- 15/10/2026 (PDD9500-9999, PNR9500-9560, PNR3400-3460, CS9500-9560). No hay
-- endpoint de listado (/claims/reasons da 404). Los PNR34xx responden con otro
-- id (PNR3430 → PNR9502): quedan como alias. Título y descripción salen de
-- `reasonFromApi` (supabase/functions/_shared/mercadolibre/reasons.ts), la
-- misma función que usa la Edge.
--
-- `excludable` es orientativo (arrepentimiento, compra por error, mejor
-- precio, compra no reconocida): ML decide cada pedido de exclusión.
-- `recommended` marca los 4 que ya venían por defecto en exclusion_reasons.
-- =============================================================================

create table if not exists ml_claim_reasons (
  id                   text primary key check (id ~ '^[A-Z]{2,4}[0-9]{3,5}$'),
  family               text not null check (family in ('PDD', 'PNR', 'CS', 'OTRO')),
  title                text not null check (char_length(title) between 1 and 160),
  description          text check (description is null or char_length(description) <= 400),
  ml_name              text check (ml_name is null or char_length(ml_name) <= 80),
  ml_detail            text check (ml_detail is null or char_length(ml_detail) <= 200),
  flow                 text check (flow is null or char_length(flow) <= 60),
  parent_id            text check (parent_id is null or char_length(parent_id) <= 20),
  alias_of             text check (alias_of is null or char_length(alias_of) <= 20),
  expected_resolutions text[] not null default '{}',
  triage               text[] not null default '{}',
  excludable           boolean not null default false,
  recommended          boolean not null default false,
  active               boolean not null default true,
  source               text not null default 'seed' check (source in ('seed', 'api')),
  fetched_at           timestamptz,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now()
);

comment on table ml_claim_reasons is
  'Maestro de motivos de reclamo de Mercado Libre (ADR-145). Plataforma: lectura authenticated, escritura service_role.';

alter table ml_claim_reasons enable row level security;
drop policy if exists ml_claim_reasons_read on ml_claim_reasons;
create policy ml_claim_reasons_read on ml_claim_reasons
  for select to authenticated using (true);
revoke all on ml_claim_reasons from anon, authenticated;
grant select on ml_claim_reasons to authenticated;
grant all on ml_claim_reasons to service_role;

drop trigger if exists ml_claim_reasons_updated_at on ml_claim_reasons;
create trigger ml_claim_reasons_updated_at before update on ml_claim_reasons
  for each row execute function set_updated_at();

